parsed.tgrl:
grl TeslaAutopilotModel {
    actor Driver {
        goal SafeTravel;           // avoid collisions and reach destination safely
        softGoal ReducedWorkload;  // minimize mental and physical effort while using Autopilot
        softGoal TrustInSystem;    // maintain confidence in Autopilot functionality
    }
    actor Autopilot {
        goal MaintainLanePosition; // keep vehicle centered in its lane using lane markings
        goal RespectSpeedSetting;  // obey the speed set by the driver (TACC)
        goal DetectObstacles;      // identify vehicles, trucks, motorcycles ahead
        goal ProvideDriverAlertnessMonitoring; // monitor steering torque, alert if hands off
        softGoal ComplianceWithTrafficRules;   // obey speed limits, lane rules, right‑of‑way
        task EmergencyBraking;     // execute automatic emergency braking when imminent collision detected
    }
    actor OtherRoadUsers {
        goal PreservePedestrianSafety; // avoid striking pedestrians or vulnerable road users
        goal AvoidCollisionWithVehicles; // maintain safe distance from cars, trucks, motorcycles
    }
    actor Sensors {
        goal CaptureCameraImages;
        goal EmitRadarSignals;
        goal ProvideUltrasonicData;
    }
    actor VisionProcessing {
        goal IdentifyLaneMarkings;
        goal DetectObjectsAhead;
    }
}

